#include <concepts>
#include <cstddef>
#include <ostream>

template <typename T>
concept Printable = requires(std::ostream& out, const T& value) { out << value; };

template <typename T>
concept HasSize = requires(const T& value) { { value.size() } -> std::convertible_to<std::size_t>; };

std::size_t sizeOf(const HasSize auto& container)
{
    return container.size();
}

unitTests:
struct Opaque {};
struct WeirdSize { void size() const {} };

static_assert(Printable<int> && Printable<std::string> && Printable<const char*>);
static_assert(!Printable<Opaque> && !Printable<std::vector<int>>);
static_assert(HasSize<std::string> && HasSize<std::vector<double>>);
static_assert(!HasSize<int> && !HasSize<Opaque>);
static_assert(!HasSize<WeirdSize>, "size() must return something convertible to std::size_t");

TEST("sizeOf") { CHECK_EQ(sizeOf(std::string{ "hello" }), 5u); CHECK_EQ(sizeOf(std::vector<int>{ 1, 2, 3 }), 3u); }

